const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');

const GRAVITY = 0.5;
const DAMPING = 0.99;
const ITERATIONS = 10;

class Particle {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.oldX = x;
    this.oldY = y;
  }

  update() {
    const vx = (this.x - this.oldX) * DAMPING;
    const vy = (this.y - this.oldY) * DAMPING;
    this.oldX = this.x;
    this.oldY = this.y;
    this.x += vx;
    this.y += vy + GRAVITY;
  }

  constrain() {
    if (this.y > canvas.height - 10) {
      this.y = canvas.height - 10;
      this.oldY = this.y + (this.y - this.oldY) * 0.5;
    }
    if (this.x < 10) {
      this.x = 10;
      this.oldX = this.x + (this.x - this.oldX) * 0.5;
    }
    if (this.x > canvas.width - 10) {
      this.x = canvas.width - 10;
      this.oldX = this.x + (this.x - this.oldX) * 0.5;
    }
  }
}

class Spring {
  constructor(p1, p2) {
    this.p1 = p1;
    this.p2 = p2;
    this.restLength = Math.hypot(p2.x - p1.x, p2.y - p1.y);
  }

  update() {
    const dx = this.p2.x - this.p1.x;
    const dy = this.p2.y - this.p1.y;
    const dist = Math.hypot(dx, dy);
    if (dist === 0) return;
    const diff = (dist - this.restLength) / dist;
    const offsetX = dx * diff * 0.5;
    const offsetY = dy * diff * 0.5;
    this.p1.x += offsetX;
    this.p1.y += offsetY;
    this.p2.x -= offsetX;
    this.p2.y -= offsetY;
  }
}

const particles = [
  new Particle(250, 100),
  new Particle(350, 100),
  new Particle(350, 200),
  new Particle(250, 200)
];

const springs = [
  new Spring(particles[0], particles[1]),
  new Spring(particles[1], particles[2]),
  new Spring(particles[2], particles[3]),
  new Spring(particles[3], particles[0]),
  new Spring(particles[0], particles[2]),
  new Spring(particles[1], particles[3])
];

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.strokeStyle = '#4a9eff';
  ctx.lineWidth = 2;
  for (const spring of springs) {
    ctx.beginPath();
    ctx.moveTo(spring.p1.x, spring.p1.y);
    ctx.lineTo(spring.p2.x, spring.p2.y);
    ctx.stroke();
  }

  ctx.fillStyle = '#ff6b6b';
  for (const particle of particles) {
    ctx.beginPath();
    ctx.arc(particle.x, particle.y, 5, 0, Math.PI * 2);
    ctx.fill();
  }
}

function animate() {
  for (const particle of particles) {
    particle.update();
  }

  for (let i = 0; i < ITERATIONS; i++) {
    for (const spring of springs) {
      spring.update();
    }
    for (const particle of particles) {
      particle.constrain();
    }
  }

  draw();
  requestAnimationFrame(animate);
}

animate();

